func ImageApplyMask(sourceLike ImageDataLike, maskLike ImageDataLike) *ImageData {
	var source *ImageData
	if sourceLike != nil {
		source = sourceLike.AsImageData()
	}
	_ = source
	var mask *ImageData
	if maskLike != nil {
		mask = maskLike.AsImageData()
	}
	_ = mask
	var imageData *ImageData
	var blackIndex int32 = 0
	if source.Palette.IsDirect {
		imageData = NewImageData(source.Width, source.Height, source.Depth, source.Palette)
	} else {
		var black *RGB = NewRGB(0, 0, 0)
		var rgbs []*RGB = source.GetRGBs()
		if source.TransparentPixel != -1 {
			var newRGBs []*RGB = make([]*RGB, int32(len(rgbs)))
			copy(newRGBs[0:], rgbs[0:0+int32(len(rgbs))])
			if source.TransparentPixel >= int32(len(newRGBs)) {
				rgbs = make([]*RGB, source.TransparentPixel+1)
				copy(rgbs[0:], newRGBs[0:0+int32(len(newRGBs))])
				for i := int32(int32(len(newRGBs))); i <= source.TransparentPixel; i++ {
					rgbs[i] = NewRGB(0, 0, 0)
				}
			} else {
				newRGBs[source.TransparentPixel] = black
				rgbs = newRGBs
			}
			blackIndex = source.TransparentPixel
			imageData = NewImageData(source.Width, source.Height, source.Depth, NewPaletteData(rgbs))
		} else {
			for blackIndex < int32(len(rgbs)) {
				if rgbs[blackIndex].Equals(black) {
					break
				}
				blackIndex++
			}
			if blackIndex == int32(len(rgbs)) {
				if (1 << source.Depth) > int32(len(rgbs)) {
					var newRGBs []*RGB = make([]*RGB, int32(len(rgbs))+1)
					copy(newRGBs[0:], rgbs[0:0+int32(len(rgbs))])
					newRGBs[int32(len(rgbs))] = black
					rgbs = newRGBs
				} else {
					blackIndex = -1
				}
			}
			imageData = NewImageData(source.Width, source.Height, source.Depth, NewPaletteData(rgbs))
		}
	}
	if blackIndex == -1 {
		copy(imageData.Data[0:], source.Data[0:0+int32(len(imageData.Data))])
	} else {
		var imagePixels []int32 = make([]int32, imageData.Width)
		var maskPixels []int32 = make([]int32, mask.Width)
		for y := int32(0); y < imageData.Height; y++ {
			source.GetPixelsXYGetWidthPixelsStartIndex(0, y, imageData.Width, imagePixels, 0)
			mask.GetPixelsXYGetWidthPixelsStartIndex(0, y, mask.Width, maskPixels, 0)
			for i := int32(0); i < int32(len(imagePixels)); i++ {
				if maskPixels[i] == 0 {
					imagePixels[i] = blackIndex
				}
			}
			imageData.SetPixelsXYPutWidthPixelsStartIndex(0, y, source.Width, imagePixels, 0)
		}
	}
	imageData.MaskPad = mask.ScanlinePad
	imageData.MaskData = mask.Data
	return imageData
}

